using System;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Collections.Generic;using ElementalHearts;using RimWorld;using Verse;
class WaterKitRegression {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static T Empty<T>(){return (T)FormatterServices.GetUninitializedObject(typeof(T));}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Set(object o,string key,object value){o.GetType().GetField(key,F).SetValue(o,value);}
 static object Get(object o,string key){return o.GetType().GetField(key,F).GetValue(o);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(WaterKitRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static void Run(){
  var pawn=Empty<Pawn>();pawn.health=Empty<Pawn_HealthTracker>();pawn.health.hediffSet=Empty<HediffSet>();pawn.health.hediffSet.hediffs=new List<Hediff>();var root=new HediffWithComps{def=new HediffDef{defName=WaterKitUpgrade.DefName},pawn=pawn,loadID=710,ageTicks=999999,comps=new List<HediffComp>()};Set(root,"severityInt",1.25f);pawn.health.hediffSet.hediffs.Add(root);
  var defense=new HediffComp_WaterDefense{parent=root,props=new HediffCompProperties_WaterDefense(),autoCombat=false,nonLethal=true,readyAt=12345};var pending=Empty<Pawn>();pending.def=Empty<ThingDef>();pending.def.defName="Human";pending.thingIDNumber=901;Set(defense,"pending",pending);Set(defense,"pendingAt",12346);
  var transform=new HediffComp_ElementalTransform{parent=root,props=new HediffCompProperties_ElementalTransform()};Set(transform,"finishAt",5000);Set(transform,"stage",1);var kit=Get(transform,"kit");var extra=new ForeignWaterKitTestComp{parent=root,value=4321};root.comps.AddRange(new HediffComp[]{defense,transform,extra});var oldList=root.comps;
  var destination=new HediffDef{defName=WaterKitUpgrade.DefName,comps=new List<HediffCompProperties>{new HediffCompProperties_ElementalAscension(),new HediffCompProperties_ElementalTransform(),new HediffCompProperties_WaterDefense(),new HediffCompProperties_LightningRecovery()}};
  Check(WaterKitUpgrade.Ensure(root,destination),"Old Water root not upgraded");Check(root.loadID==710&&root.ageTicks==999999&&root.Severity==1.25f&&root.def==destination&&object.ReferenceEquals(root.comps,oldList),"Upgrade replaced identity/age/severity/comp list");Check(root.TryGetComp<HediffComp_WaterDefense>()==defense&&!defense.autoCombat&&defense.nonLethal&&defense.readyAt==12345&&object.ReferenceEquals(Get(defense,"pending"),pending)&&(int)Get(defense,"pendingAt")==12346,"Water defense state reset");Check(root.TryGetComp<HediffComp_ElementalTransform>()==transform&&object.ReferenceEquals(kit,Get(transform,"kit"))&&(int)Get(transform,"finishAt")==5000&&(int)Get(transform,"stage")==1,"Transformation/kit state reset");Check(root.comps.Contains(extra)&&extra.value==4321&&root.comps.Count==5,"Foreign saved comp lost or duplicates added");var recovery=root.TryGetComp<HediffComp_LightningRecovery>();Check(recovery!=null&&recovery.Props.sealAfterTicks==180&&recovery.Props.healPerSecond==2,"Normal recovery not bound");Set(recovery,"elapsed",19);Check(!WaterKitUpgrade.Ensure(root,destination)&&root.comps.Count==5&&(int)Get(recovery,"elapsed")==19,"Repeat upgrade recreates comps or resets timers");foreach(var comp in root.comps)Check(comp.parent==root,"Comp holder link broken");
  var foreign=new HediffWithComps{def=new HediffDef{defName="EH_FlameHeart"},comps=new List<HediffComp>()};Check(!WaterKitUpgrade.Ensure(foreign,destination)&&foreign.def.defName=="EH_FlameHeart"&&foreign.comps.Count==0,"Water migration touches another element");Check(WaterKitUpgrade.HasAscension(pawn)&&!WaterKitUpgrade.HasAscension(null),"Water full-ascension identity invalid");
  Check(defense.Props.parryChance==.8f&&defense.Props.recoveryTicks==45&&defense.Props.counterMultiplier==1.6f,"Existing defense tuning changed");
  Console.WriteLine("PASS: same saved Water root/list/defense/transform/foreign comp identities retained, including modes, recovery/counter timing, pending target, kit references and repeat-safe upgrade.");
  Check(!(bool)typeof(HediffComp_ElementalTransform).GetProperty("Available",F).GetValue(transform,null),"Missing gear incorrectly available");foreach(string suffix in new[]{"Uniform","Helmet","Sword"}){var def=Empty<ThingDef>();def.defName="EH_Water"+suffix;DefDatabase<ThingDef>.Add(def);}Check((bool)typeof(HediffComp_ElementalTransform).GetProperty("Available",F).GetValue(transform,null),"Complete Water kit still unavailable");Check((string)typeof(HediffComp_ElementalTransform).GetProperty("EquipmentElement",F).GetValue(transform,null)=="Water","Water selects another element's gear");
  var marker=Empty<ThingDef>();marker.modExtensions=new List<DefModExtension>{new IndestructibleElementalGear()};var gear=new ThingWithComps{def=marker};DamageWorker.DamageResult result=null;Check(!ElementalGearNoDamage.Prefix(gear,ref result)&&result!=null&&result.totalDamageDealt==0,"Indestructible Water gear policy fails");Check(!ElementalHearts.Patches.WaterNoHitSlowdown.Prefix(pawn,ref DummyResult.value),"Water normal resilience does not suppress hit stagger");
  Console.WriteLine("PASS: production transform availability switches on with Water's three gear defs, Water equipment identity, indestructible gear handling and full-Water stagger protection.");
  var payload=new WaterKitSaveCase{defense=defense,transform=transform,recovery=recovery,target=new WaterKitReferenceStub{loadID=pending.GetUniqueLoadID()}};string file=Path.Combine(Path.GetTempPath(),"WaterKit_"+Guid.NewGuid().ToString("N")+".xml");Scribe.saver.InitSaving(file,"WaterKitTest");Scribe_Deep.Look(ref payload,"state");Scribe.saver.FinalizeSaving();var xml=new System.Xml.XmlDocument();xml.Load(file);Check(xml.SelectSingleNode("WaterKitTest/state/waterAuto").InnerText=="False"&&xml.SelectSingleNode("WaterKitTest/state/waterNonLethal").InnerText=="True"&&xml.SelectSingleNode("WaterKitTest/state/waterReadyAt").InnerText=="12345"&&xml.SelectSingleNode("WaterKitTest/state/waterCounterAt").InnerText=="12346"&&xml.SelectSingleNode("WaterKitTest/state/waterCounterTarget").InnerText.Contains("901"),"Existing native defense save keys/state lost");Check(xml.SelectSingleNode("WaterKitTest/state/transformFinish").InnerText=="5000"&&xml.SelectSingleNode("WaterKitTest/state/EH_recoveryElapsed").InnerText=="19","Recovery/transform save keys lost");File.Delete(file);
  Console.WriteLine("PASS: native Scribe save output retains waterAuto, waterNonLethal, waterReadyAt, waterCounterTarget, waterCounterAt, transformation progress and independent recovery elapsed.");Console.WriteLine("LIMIT: native loading, actual healing, gear creation/equipping and live rendering/combat remain in-game checks.");
 }
 static class DummyResult{public static bool value;}
}
public class ForeignWaterKitTestComp:HediffComp {public int value;}
public class WaterKitSaveCase:IExposable {public HediffComp_WaterDefense defense;public HediffComp_ElementalTransform transform;public HediffComp_LightningRecovery recovery;public WaterKitReferenceStub target;public void ExposeData(){Scribe_Deep.Look(ref target,"targetFixture");defense.CompExposeData();transform.CompExposeData();recovery.CompExposeData();}}

// Minimal deep-saved target stub satisfies native reference checking; full Pawn loading is outside this fixture.
public class WaterKitReferenceStub:IExposable,ILoadReferenceable {public string loadID;public string GetUniqueLoadID(){return loadID;}public void ExposeData(){Scribe_Values.Look(ref loadID,"loadID");}}
